// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Panel with a model table below the fold – its rendering is skipped while off-screen; the placeholder
//          height is estimated from the row count (auto keeps the real size once rendered).
function DeferredPanel({ model }: { model: TableModel }) {
  return (
    <div style={{ contentVisibility: 'auto', containIntrinsicSize: `auto none auto ${96 + model.rows.length * 26}px` }}>
      <Panel title={model.title}>
        <ListTable head={model.header} label={model.title}>
          {model.rows.map((r) => (
            <tr key={r.head}>
              <RowHeader>{r.head}</RowHeader>
              {r.cells.map((c, i) => (
                <td key={i}>{c.text}</td>
              ))}
            </tr>
          ))}
        </ListTable>
      </Panel>
    </div>
  )
}
